import { AuthPasskey } from "@/components/design-for-ai/auth-passkey";

<AuthPasskey
  brand="Acme"
  onAuthenticate={async (signal) => {
    const options = await fetch("/api/passkey/options").then((r) => r.json());
    const credential = await navigator.credentials.get({ publicKey: options, signal });
    const user = await fetch("/api/passkey/verify", { method: "POST", body: JSON.stringify(credential) }).then((r) => r.json());
    return { name: user.name };
  }}
  onSuccess={() => router.push("/app")}
  onFallback={() => setMode("email")}
/>
